import { decodePolyline } from '@helpers/gpsHelper';

import { IHikingGpxPoint } from '../../Hiking/@types/hiking.types';
import {
  IBaseWorkoutDTO,
  IWorkoutFullDTO,
  IWorkoutListDTO,
  IWorkoutTagDTO,
  IWorkoutTypeDTO,
} from '../@types/DTO/workouts.dto.types';
import {
  IWorkout,
  IWorkoutTag,
  IWorkoutType,
  IWorkoutFull,
  IBaseWorkout,
} from '../@types/workouts.types';

export const mapWorkoutType = (backData: IWorkoutTypeDTO): IWorkoutType => {
  return {
    id: +backData.id,
    name: backData.name,
  };
};

export const mapBaseWorkoutToFront = (backData: IBaseWorkoutDTO): IBaseWorkout => {
  return {
    id: +backData.id,
    name: backData.name,
    type: {
      id: +backData.workout_type_id,
      name: backData.workout_type_name,
    },

    date_start: new Date(backData.date_start),
    date_finish: new Date(backData.date_finish),
    distance: +backData.distance,
  };
};

export const mapWorkoutToFront = (backData: IWorkoutListDTO): IWorkout => {
  return {
    ...mapBaseWorkoutToFront(backData),
    description: backData.description,
    user: {
      id: +backData.id_user,
      name: [backData.user_name, backData.user_surname].join(' '),
      photo: backData.user_photo,
    },
    group: !backData.workout_group
      ? null
      : {
          id: +backData.workout_group,
          name: backData.workout_group_name,
        },
    hiking: !backData.hiking_id
      ? null
      : {
          id: +backData.hiking_id,
          name: backData.hiking_name,
          ava: backData.hiking_ava,
          start: new Date(backData.hiking_start),
          finish: new Date(backData.hiking_finish),
        },
    id_workout_track: +backData.id_workout_track,

    date_upload: new Date(backData.date_upload),
    date_update: backData.date_update ? new Date(backData.date_update) : null,

    activity_type: backData.activity_type,
    distance: +backData.distance,
    alt_ascent: +backData.alt_ascent,
    alt_descent: +backData.alt_descent,
    alt_max: +backData.alt_max,
    alt_min: +backData.alt_min,
    alt_avg: +backData.alt_avg,
    speed_max: +backData.speed_max,
    speed_min: +backData.speed_min,
    speed_avg: +backData.speed_avg,
    hr_max: backData.hr_max ? +backData.hr_max : null,
    hr_min: backData.hr_min ? +backData.hr_min : null,
    hr_avg: backData.hr_avg ? +backData.hr_avg : null,
    temp_max: backData.temp_max ? +backData.temp_max : null,
    temp_min: backData.temp_min ? +backData.temp_min : null,
    temp_avg: backData.temp_avg ? +backData.temp_avg : null,
    time_mooving: +backData.time_mooving,
    time_pause: +backData.time_pause,
    photos: backData.photos.map((p) => {
      return {
        id: +p.id,
        url_preview: p.url_preview,
        url: p.url,
        is_main: p.is_main == '1',
      };
    }),
    tags: backData.tags.map((t) => {
      return {
        id: +t.id,
        name: t.name,
        color: t.color,
        is_personal: t.is_personal == '1',
      };
    }),
    points: backData.trackdata
      ? (decodePolyline(backData.trackdata).map(([la, lo, alt]) => [
          la,
          lo,
          alt,
        ]) as IHikingGpxPoint['point'][])
      : [],
  };
};

export const mapWorkoutFullToFront = (backData: IWorkoutFullDTO): IWorkoutFull => {
  const coords = decodePolyline(backData.trackdata).map(([la, lo, alt]) => [
    la,
    lo,
    alt,
  ]) as IHikingGpxPoint['point'][];
  let dateInc = +new Date(backData.date_start) / 1000;

  const trackMeta = decodePolyline(backData.trackmeta);

  const isOwnTrack = +backData.id_user === +backData.track_owner_id;

  const track: IHikingGpxPoint[] = coords.map((point, index) => {
    const [ts, hr = null, temp = null] = trackMeta[index];
    dateInc += ts;
    const date = new Date(dateInc * 1e3);
    return {
      date,
      point,
      hr: isOwnTrack && hr ? hr : undefined, // Не мапим пульс когда трек чужой (которым поделились)
      temp: temp ?? undefined,
    };
  });

  return {
    ...mapWorkoutToFront(backData),
    track,
    trackOwner: {
      id: +backData.track_owner_id,
      name: backData.track_owner_name,
      surname: backData.track_owner_surname,
      photo: backData.track_owner_photo,
    },
    photos: backData.photos.map((p) => {
      return {
        id: +p.id,
        url_preview: p.url_preview,
        url: p.url,
        date: new Date(p.date),
        comment: p.comment,
        coordinates: p.lon && p.lat ? [+p.lat, +p.lon, parseInt(p.altitude ?? '0')] : null,
        is_main: p.is_main == '1',
        created: {
          date: new Date(p.created_at),
          user: {
            id: +p.creator_id,
            name: p.creator_name,
            surname: p.creator_surname,
            photo: p.creator_photo,
          },
        },
      };
    }),
    tags: backData.tags.map((t) => {
      return {
        id: +t.id,
        createdAt: new Date(t.created_at),
        tag: {
          id: +t.tag_id,
          name: t.name,
          color: t.color,
          is_personal: t.is_personal == '1',
        },
      };
    }),
  };
};

export const mapWorkoutTagToFront = (backData: IWorkoutTagDTO): IWorkoutTag => {
  return {
    id: +backData.id,
    name: backData.name,
    color: backData.color,
    is_personal: backData.is_personal == '1',
  };
};
